const sumAmountMinor = (items: readonly Opportunity[]) => items.reduce((total, item) => total + item.amountMinor, 0);

export const opportunityIndicators = (opportunities: readonly Opportunity[]): OpportunityIndicators => {
  const open = opportunities.filter((opportunity) => isOpenStage(opportunity.stage));
  const won = opportunities.filter((opportunity) => opportunity.stage === 'WON');
  const lost = opportunities.filter((opportunity) => opportunity.stage === 'LOST');
  const closedCount = won.length + lost.length;
  return {
    byStage: OpportunityStageSchema.literals.map((stage) => {
      const items = opportunities.filter((opportunity) => opportunity.stage === stage);
      return { count: items.length, stage, valueMinor: sumAmountMinor(items) };
    }),
    lostCount: lost.length,
    openCount: open.length,
    openValueMinor: sumAmountMinor(open),
    weightedValueMinor: open.reduce(
      (total, opportunity) => total + Math.round((opportunity.amountMinor * opportunity.probability) / 100),
      0,
    ),
    winRate: closedCount === 0 ? Option.none() : Option.some(won.length / closedCount),
    wonCount: won.length,
    wonValueMinor: sumAmountMinor(won),
  };
};

