export const visibleOpportunities = Effect.fn('SalesPipeline.visibleOpportunities')(function* visibleOpportunities(
  opportunities: readonly Opportunity[],
  scope: OperationalScope,
) {
  const access = yield* ContextAccess;
  if (yield* contextGrant(scope, 'read_all')) {
    return opportunities;
  }
  if (scope.legalEntityId === undefined) {
    return yield* referenceUnavailable();
  }
  const targets = opportunities.map((opportunity) => opportunityTarget(opportunity.id));
  const keys = targets.map(targetKey);
  const decisions = yield* access.resources({
    legalEntityId: scope.legalEntityId,
    principalId: scope.principalId,
    resources: targets,
    tenantId: scope.tenantId,
  });
  if (
    decisions.length !== opportunities.length ||
    decisions.some((decision, index) => decision.decision === 'unavailable' || decision.key !== keys[index])
  ) {
    return yield* referenceUnavailable();
  }
  return opportunities.filter((_, index) => decisions[index]?.decision === 'allowed');
});

